Python標準機能だけで分類と遅延の不変条件を検査する合成例。実行者が許可されたローカル環境で実行する。外部接続・ファイル操作はなく、実キューのAPIや状態遷移を模造するものではない。現在は未実行であり、実機の合格根拠にはならない。

```python
import copy

# kindは調査後の分類。エラー文字列から自動確定しない。
def plan(job, now, delay):
    if delay <= 0:
        raise ValueError('positive delay required')
    if job['kind'] == 'missing_confirmed' and job['approved']:
        return {'action': 'isolate', 'next_at': None}
    if job['kind'] == 'transient_transport':
        return {'action': 'retry', 'next_at': now + delay}
    return {'action': 'hold', 'next_at': None}

def valid(job, result, now, delay):
    if job['kind'] == 'transient_transport':
        return (result['action'] == 'retry'
                and result['next_at'] is not None
                and result['next_at'] >= now + delay)
    if job['kind'] == 'missing_confirmed' and job['approved']:
        return result == {'action': 'isolate', 'next_at': None}
    return result == {'action': 'hold', 'next_at': None}

jobs = [
    {'id': 'a', 'kind': 'missing_confirmed', 'approved': True},
    {'id': 'b', 'kind': 'transient_transport', 'approved': False},
    {'id': 'c', 'kind': 'permission_denied', 'approved': True},
    {'id': 'd', 'kind': 'missing_confirmed', 'approved': False},
    {'id': 'e', 'kind': 'mount_unknown', 'approved': True},
]
before = copy.deepcopy(jobs)
now, delay = 100, 7  # 合成時刻。実運用の推奨秒数ではない。
results = [plan(j, now, delay) for j in jobs]
expected = [
    {'action': 'isolate', 'next_at': None},
    {'action': 'retry', 'next_at': 107},
    {'action': 'hold', 'next_at': None},
    {'action': 'hold', 'next_at': None},
    {'action': 'hold', 'next_at': None},
]
assert results == expected
assert jobs == before
assert all(valid(j, r, now, delay) for j, r in zip(jobs, results))
# 負例：即時再試行・通信障害の隔離・未確定入力の隔離を拒否する。
assert not valid(jobs[1], {'action': 'retry', 'next_at': 100}, now, delay)
assert not valid(jobs[1], {'action': 'isolate', 'next_at': None}, now, delay)
assert not valid(jobs[2], {'action': 'isolate', 'next_at': None}, now, delay)
try:
    plan(jobs[1], now, 0)
except ValueError:
    pass
else:
    raise AssertionError('zero delay accepted')
print('分類方針fixtureのみ合格')
```

全assert通過・終了コード0がこの例の終了条件。失敗時は規則を修正するまで対象環境への適用に進まない。
